"""Roman numerals for the integers 1 to 3999, such as 1994 -> "MCMXCIV"."""
import re

_VALUES = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]
_CANONICAL = re.compile(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})")
_LETTERS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def to_roman(n):
    """Upper-case numeral for n, which must be an integer from 1 to 3999."""
    if not isinstance(n, int) or not 1 <= n <= 3999:
        raise ValueError(f"out of range 1-3999: {n!r}")
    parts = []
    for value, numeral in _VALUES:
        count, n = divmod(n, value)
        parts.append(numeral * count)
    return "".join(parts)


def from_roman(s):
    """Integer for a canonical upper-case numeral such as "MCMXCIV". Anything to_roman would not produce is an error."""
    if not s or not _CANONICAL.fullmatch(s):
        raise ValueError(f"not a canonical roman numeral: {s!r}")
    total = 0
    for i, ch in enumerate(s):
        value = _LETTERS[ch]
        if i + 1 < len(s) and _LETTERS[s[i + 1]] > value:
            total -= value
        else:
            total += value
    return total
