"""Each registered command's README cell must equal its help string, word for word."""
import pathlib
import re
import unittest

from textkit.cli import COMMANDS

ROOT = pathlib.Path(__file__).resolve().parent.parent


class DocSyncTest(unittest.TestCase):
    def setUp(self):
        readme = (ROOT / "README.md").read_text(encoding="utf-8")
        # Table rows look like: | `name` | what it does |
        self.cells = dict(re.findall(r"^\| `([a-z]+)` \| (.*?) \|$", readme, flags=re.M))

    def test_every_command_has_matching_readme_cell(self):
        for name, c in COMMANDS.items():
            with self.subTest(command=name):
                self.assertIn(name, self.cells, "no README table row")
                self.assertEqual(self.cells[name], c["help"])


if __name__ == "__main__":
    unittest.main()
