import contextlib
import io
import unittest

from textkit.cli import main
from textkit.rot import rot


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class RotTest(unittest.TestCase):
    def test_rot13_examples(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")

    def test_keeps_case_and_wraps(self):
        self.assertEqual(rot("xyzXYZ", 3), "abcABC")

    def test_other_characters_unchanged(self):
        self.assertEqual(rot("1 2-3_!? é ü", 5), "1 2-3_!? é ü")

    def test_negative_n(self):
        self.assertEqual(rot("abc", -1), "zab")

    def test_large_n(self):
        self.assertEqual(rot("abc", 27), "bcd")
        self.assertEqual(rot("abc", 26), "abc")
        self.assertEqual(rot("abc", 10**20), rot("abc", 10**20 % 26))

    def test_zero_is_identity(self):
        self.assertEqual(rot("Any Text", 0), "Any Text")

    def test_round_trip(self):
        for n in range(-30, 31):
            with self.subTest(n=n):
                self.assertEqual(rot(rot("The Quick Fox", n), -n), "The Quick Fox")

    def test_non_int_raises(self):
        for bad in [1.5, "13", None, True, False]:
            with self.subTest(n=bad):
                with self.assertRaises(ValueError):
                    rot("abc", bad)


class RotCommandTest(unittest.TestCase):
    def test_default_is_rot13(self):
        self.assertEqual(run("rot", "Hello, World!"), (0, "Uryyb, Jbeyq!\n", ""))

    def test_negative_n(self):
        self.assertEqual(run("rot", "abc", "--n", "-1"), (0, "zab\n", ""))

    def test_large_n(self):
        self.assertEqual(run("rot", "abc", "--n", "27"), (0, "bcd\n", ""))

    def test_non_integer_is_error(self):
        for bad in ["1.5", "abc", ""]:
            with self.subTest(n=bad):
                code, out, err = run("rot", "abc", "--n", bad)
                self.assertEqual(code, 2)
                self.assertEqual(out, "")
                self.assertTrue(err.startswith("error:"))

    def test_listed_in_commands(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("rot", out.split())


if __name__ == "__main__":
    unittest.main()

